function lesson(record) {
  const {checkpointAfter=2,checkpoint,technicalPart=3,...rest}=record;
  const parts=record.parts.map((part,i)=>({...part,title:`${i+1}. ${part.title}`}));
  return {...rest,section:'NoSQL',parts,technicalStart:parts[technicalPart-1].title,checkpoints:[{after:parts[checkpointAfter-1].title,title:`Questions on Parts 1 to ${checkpointAfter}`,questions:checkpoint}]};
}
