const bad=call=>`try:\n    ${call}\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("Expected ValueError for malformed input")`;
const checks=`def whole(value):
    return type(value) is int and value >= 0

def text(value):
    return isinstance(value, str) and bool(value.strip())
`;

const loadSolution=`${checks}
def partition_load(rows, fields, capacity):
    if not isinstance(rows, list) or not isinstance(fields, list) or not fields or not all(text(k) for k in fields) or len(set(fields)) != len(fields) or not whole(capacity):
        raise ValueError("Invalid key or capacity")
    groups = {}
    for row in rows:
        if not isinstance(row, dict) or not whole(row.get("load")) or not all(text(row.get(k)) for k in fields):
            raise ValueError("Invalid request measurement")
        key = tuple(row[k] for k in fields)
        groups[key] = groups.get(key, 0) + row["load"]
    return [{"key":list(key),"load":load,"overloaded":load > capacity}
            for key, load in groups.items()]

requests = [{"tenant":"north","asset":"P7","load":6},
            {"tenant":"north","asset":"P8","load":4}]
print(partition_load(requests, ["tenant", "asset"], 7))`;
